insert into public.assessment_domains (id, title, blurb, icon, position, active) values
  (1, 'Physical and cardiometabolic health', 'Your details and recent health history.', 'monitor_heart', 1, true),
  (2, 'Dietary behaviours and food security', 'Think about the last 7 days. Each question shows what one serving looks like.', 'restaurant', 2, true),
  (3, 'Academic workload and time pressure', 'How study fits around the rest of life.', 'school', 3, true),
  (4, 'Emotional well-being and stress', 'How you have been feeling. These are screening questions, not a diagnosis.', 'psychology', 4, true),
  (5, 'Sleep and daily routines', 'Rest and the rhythm of your days.', 'bedtime', 5, true),
  (6, 'Physical activity and sedentary behaviour', 'Moving and sitting through the week.', 'directions_walk', 6, true),
  (7, 'Financial and living conditions', 'Where you stay and how money affects health.', 'savings', 7, true),
  (8, 'Social environment and personal support', 'The people around you.', 'diversity_3', 8, true),
  (9, 'Campus environment and access to services', 'Food, spaces and health services on campus.', 'local_hospital', 9, true),
  (10, 'Student voice and institutional priorities', 'What the university should do next.', 'campaign', 10, true),
  (11, 'Clinical measurements', 'Your latest measured values. Skip any you do not have.', 'stethoscope', 11, true)
insert into public.assessment_questions (id, domain_id, position, kind, style, text, help, image, options, unit, min_value, max_value, max_choices, prefill, optional, show_if, active) values
  ('p_profile', 1, 1, 'profile', null, 'Are your details still correct?', 'We filled these in from your profile. Update anything that has changed.', null, '[{"value": "same", "label": "Yes, all correct"}, {"value": "updated", "label": "I updated my details"}]'::jsonb, null, null, null, null, null, false, null, true),
  ('p_general', 1, 2, 'scale', null, 'How would you rate your overall physical health right now?', null, null, '[{"value": "1", "label": "Poor", "score": 0}, {"value": "2", "label": "Fair", "score": 1}, {"value": "3", "label": "Good", "score": 2}, {"value": "4", "label": "Very good", "score": 3}, {"value": "5", "label": "Excellent", "score": 4}]'::jsonb, null, null, null, null, null, false, null, true),
  ('p_new_dx', 1, 3, 'multi', null, 'In the last 6 months, has a doctor or nurse told you that you have any of these?', 'Select all that apply.', null, '[{"value": "high_bp", "label": "High blood pressure"}, {"value": "diabetes", "label": "Diabetes or prediabetes"}, {"value": "cholesterol", "label": "High cholesterol"}, {"value": "heart", "label": "Heart or blood vessel disease"}, {"value": "other", "label": "Another long-term condition"}, {"value": "none", "label": "None of these"}, {"value": "pns", "label": "Prefer not to say"}]'::jsonb, null, null, null, null, null, false, null, true),
  ('p_substance', 1, 4, 'multi', null, 'Do you currently use any of these?', 'Optional and confidential. Answers are pooled with other students and never linked to your name. If you would like support to cut down or quit, the health centre and counsellors can help without judgement.', null, '[{"value": "tobacco", "label": "Cigarettes or other tobacco (including beedi)"}, {"value": "vape", "label": "E-cigarettes or vapes"}, {"value": "alcohol", "label": "Alcohol"}, {"value": "cannabis", "label": "Cannabis (ganja)"}, {"value": "nonpres", "label": "Medicines not prescribed to me, taken to feel high"}, {"value": "other", "label": "Other substances"}, {"value": "none", "label": "None of these"}, {"value": "pns", "label": "Prefer not to say"}]'::jsonb, null, null, null, null, null, true, null, true),
  ('d_breakfast', 2, 1, 'single', 'days', 'In the last 7 days, on how many days did you eat breakfast?', 'Anything substantial before your first lecture counts: bread, hoppers, string hoppers, oats, milk rice or a rice meal.', 'food_groups/breakfast.webp', '[{"value": "0", "label": "0 days", "score": 0}, {"value": "1-3", "label": "1 to 3 days", "score": 1}, {"value": "4-6", "label": "4 to 6 days", "score": 2}, {"value": "7", "label": "Every day", "score": 3}]'::jsonb, null, null, null, null, null, false, null, true),
  ('d_veg', 2, 2, 'single', 'days', 'On how many days did you eat 2 or more servings of vegetables?', '1 serving = ½ cup of cooked vegetables or mallum (one cupped hand), or 1 cup of raw salad (one fist). Potatoes do not count.', 'food_groups/other_veg.webp', '[{"value": "0", "label": "0 days", "score": 0}, {"value": "1-3", "label": "1 to 3 days", "score": 1}, {"value": "4-6", "label": "4 to 6 days", "score": 2}, {"value": "7", "label": "Every day", "score": 3}]'::jsonb, null, null, null, null, null, false, null, true),
  ('d_greens', 2, 3, 'single', 'days', 'On how many days did you eat dark green leafy vegetables?', 'Gotukola, mukunuwenna, kankun, spinach or kathurumurunga. 1 serving = ½ cup cooked or as mallum (one cupped hand).', 'food_groups/dark_leafy.webp', '[{"value": "0", "label": "0 days", "score": 0}, {"value": "1-2", "label": "1 to 2 days", "score": 1}, {"value": "3-4", "label": "3 to 4 days", "score": 2}, {"value": "5-7", "label": "5 to 7 days", "score": 3}]'::jsonb, null, null, null, null, null, false, null, true),
  ('d_fruit', 2, 4, 'single', 'days', 'On how many days did you eat at least 1 serving of fruit?', '1 serving = 1 medium fruit (banana, orange, guava) or ½ cup of cut fruit such as papaya, pineapple or mango (one cupped hand). Fruit juice does not count.', 'food_groups/other_fruit.webp', '[{"value": "0", "label": "0 days", "score": 0}, {"value": "1-3", "label": "1 to 3 days", "score": 1}, {"value": "4-6", "label": "4 to 6 days", "score": 2}, {"value": "7", "label": "Every day", "score": 3}]'::jsonb, null, null, null, null, null, false, null, true),
  ('d_pulses', 2, 5, 'single', 'days', 'On how many days did you eat pulses?', 'Dhal (parippu), chickpeas (kadala), green gram, cowpea or soya meat. 1 serving = ½ cup cooked (one cupped hand).', 'food_groups/pulses.webp', '[{"value": "0", "label": "0 days", "score": 0}, {"value": "1-2", "label": "1 to 2 days", "score": 1}, {"value": "3-4", "label": "3 to 4 days", "score": 2}, {"value": "5-7", "label": "5 to 7 days", "score": 3}]'::jsonb, null, null, null, null, null, false, null, true),
  ('d_protein', 2, 6, 'single', 'days', 'On how many days did you eat fish, eggs or chicken?', '1 serving = 1 egg, or a piece of fish or chicken about the size of your palm.', 'food_groups/meat_fish.webp', '[{"value": "0", "label": "0 days", "score": 0}, {"value": "1-2", "label": "1 to 2 days", "score": 1}, {"value": "3-4", "label": "3 to 4 days", "score": 2}, {"value": "5-7", "label": "5 to 7 days", "score": 3}]'::jsonb, null, null, null, null, null, false, null, true),
  ('d_wholegrain', 2, 7, 'single', 'days', 'On how many days was your main starch a whole grain?', 'Red or brown rice, kurakkan, atta flour roti or bread, or oats. 1 serving = 1 cup of cooked rice (one fist) or 1 roti.', 'food_groups/grains.webp', '[{"value": "0", "label": "0 days", "score": 0}, {"value": "1-2", "label": "1 to 2 days", "score": 1}, {"value": "3-4", "label": "3 to 4 days", "score": 2}, {"value": "5-7", "label": "5 to 7 days", "score": 3}]'::jsonb, null, null, null, null, null, false, null, true),
  ('d_dairy', 2, 8, 'single', 'days', 'On how many days did you have milk, curd or yoghurt?', '1 serving = 1 glass of milk (200 ml) or 1 small cup of curd or yoghurt (about 100 g).', 'food_groups/dairy.webp', '[{"value": "0", "label": "0 days", "score": 0}, {"value": "1-2", "label": "1 to 2 days", "score": 1}, {"value": "3-4", "label": "3 to 4 days", "score": 2}, {"value": "5-7", "label": "5 to 7 days", "score": 3}]'::jsonb, null, null, null, null, null, false, null, true),
  ('d_sugary', 2, 9, 'single', 'days', 'On how many days did you have sugary drinks or sweets?', 'Soft drinks, sweet tea or coffee, packet juice, cake, chocolate, kavum or ice cream. 1 serving = 1 glass or small bottle (200 ml), or 1 piece of a sweet.', 'food_groups/ssb.webp', '[{"value": "0", "label": "0 days", "score": 3}, {"value": "1-2", "label": "1 to 2 days", "score": 2}, {"value": "3-4", "label": "3 to 4 days", "score": 1}, {"value": "5-7", "label": "5 to 7 days", "score": 0}]'::jsonb, null, null, null, null, null, false, null, true),
  ('d_fried', 2, 10, 'single', 'days', 'On how many days did you eat short eats, fried food or fast food?', 'Rolls, patties, cutlets, vadai, kottu, fried rice, instant noodles or burgers. 1 serving = 1 short eat or 1 plate.', 'food_groups/fried_out.webp', '[{"value": "0", "label": "0 days", "score": 3}, {"value": "1-2", "label": "1 to 2 days", "score": 2}, {"value": "3-4", "label": "3 to 4 days", "score": 1}, {"value": "5-7", "label": "5 to 7 days", "score": 0}]'::jsonb, null, null, null, null, null, false, null, true),
  ('d_balanced', 2, 11, 'single', null, 'How often were your main meals balanced?', 'A balanced meal has a starch (rice, roti or hoppers), vegetables and a protein (dhal, egg, fish, chicken or soya), like the healthy plate.', 'plate/plate_hero.webp', '[{"value": "almost_always", "label": "Almost always", "score": 3}, {"value": "often", "label": "Often", "score": 2}, {"value": "sometimes", "label": "Sometimes", "score": 1}, {"value": "rarely", "label": "Rarely or never", "score": 0}]'::jsonb, null, null, null, null, null, false, null, true),
  ('d_rating', 2, 12, 'scale', null, 'Overall, how healthy was your diet this week?', null, null, '[{"value": "1", "label": "Very unhealthy", "score": 0}, {"value": "2", "label": "Somewhat unhealthy", "score": 1}, {"value": "3", "label": "In between", "score": 2}, {"value": "4", "label": "Fairly healthy", "score": 3}, {"value": "5", "label": "Very healthy", "score": 4}]'::jsonb, null, null, null, null, null, false, null, true),
  ('d_skip_money', 2, 13, 'single', null, 'In the last month, did you skip meals or eat less because money was short?', null, null, '[{"value": "never", "label": "Never", "score": 3}, {"value": "once", "label": "Once or twice", "score": 2}, {"value": "sometimes", "label": "Sometimes", "score": 1}, {"value": "often", "label": "Often", "score": 0}]'::jsonb, null, null, null, null, null, false, null, true),
  ('a_load', 3, 1, 'scale', null, 'How manageable is your academic workload right now?', null, null, '[{"value": "1", "label": "Very hard", "score": 0}, {"value": "2", "label": "Hard", "score": 1}, {"value": "3", "label": "Okay", "score": 2}, {"value": "4", "label": "Manageable", "score": 3}, {"value": "5", "label": "Very manageable", "score": 4}]'::jsonb, null, null, null, null, null, false, null, true),
  ('a_interfere', 3, 2, 'single', null, 'How often has your academic workload got in the way of your meals, sleep or well-being?', null, null, '[{"value": "never", "label": "Never", "score": 4}, {"value": "rarely", "label": "Rarely", "score": 3}, {"value": "sometimes", "label": "Sometimes", "score": 2}, {"value": "often", "label": "Often", "score": 1}, {"value": "very_often", "label": "Very often", "score": 0}]'::jsonb, null, null, null, null, null, false, null, true),
  ('e_mood', 4, 1, 'scale', null, 'Overall, how has your mood been over the past two weeks?', null, null, '[{"value": "1", "label": "Very low", "score": 0}, {"value": "2", "label": "Low", "score": 1}, {"value": "3", "label": "Okay", "score": 2}, {"value": "4", "label": "Good", "score": 3}, {"value": "5", "label": "Great", "score": 4}]'::jsonb, null, null, null, null, null, false, null, true),
  ('e_phq1', 4, 2, 'single', 'faces', 'Over the last 2 weeks, how often have you been bothered by little interest or pleasure in doing things?', null, null, '[{"value": "0", "label": "Not at all", "score": 3}, {"value": "1", "label": "Several days", "score": 2}, {"value": "2", "label": "More than half the days", "score": 1}, {"value": "3", "label": "Nearly every day", "score": 0}]'::jsonb, null, null, null, null, null, false, null, true),
  ('e_phq2', 4, 3, 'single', 'faces', 'Over the last 2 weeks, how often have you been bothered by feeling down, depressed or hopeless?', null, null, '[{"value": "0", "label": "Not at all", "score": 3}, {"value": "1", "label": "Several days", "score": 2}, {"value": "2", "label": "More than half the days", "score": 1}, {"value": "3", "label": "Nearly every day", "score": 0}]'::jsonb, null, null, null, null, null, false, null, true),
  ('s_hours', 5, 1, 'single', 'slider', 'How many hours do you usually sleep a night?', null, null, '[{"value": "<5", "label": "Less than 5 hours", "icon": "bedtime_off", "score": 0}, {"value": "5-6", "label": "5 to 6 hours", "icon": "bedtime", "score": 1}, {"value": "7-8", "label": "7 to 8 hours", "icon": "nights_stay", "score": 3}, {"value": ">8", "label": "More than 8 hours", "icon": "hotel", "score": 2}]'::jsonb, null, null, null, null, null, false, null, true),
  ('s_quality', 5, 2, 'single', 'faces', 'How would you rate your sleep quality over the past month?', null, null, '[{"value": "very_bad", "label": "Very bad", "score": 0}, {"value": "fairly_bad", "label": "Fairly bad", "score": 1}, {"value": "fairly_good", "label": "Fairly good", "score": 2}, {"value": "very_good", "label": "Very good", "score": 3}]'::jsonb, null, null, null, null, null, false, null, true),
  ('s_regular', 5, 3, 'single', null, 'Do you go to bed and wake up at about the same times most days?', null, null, '[{"value": "mostly", "label": "Mostly, yes", "score": 2}, {"value": "sometimes", "label": "Sometimes", "score": 1}, {"value": "rarely", "label": "Rarely", "score": 0}]'::jsonb, null, null, null, null, null, false, null, true),
  ('m_active_days', 6, 1, 'single', 'slider', 'In the last 7 days, on how many days were you active for at least 30 minutes?', 'Brisk walking, sport, gym, cycling or dancing all count.', null, '[{"value": "0", "label": "0 days", "hint": "Not active", "image": "activity/level_0.webp", "score": 0}, {"value": "1-2", "label": "1 to 2 days", "hint": "A little active", "image": "activity/level_1.webp", "score": 1}, {"value": "3-4", "label": "3 to 4 days", "hint": "Fairly active", "image": "activity/level_2.webp", "score": 2}, {"value": "5-7", "label": "5 to 7 days", "hint": "Very active", "image": "activity/level_3.webp", "score": 3}]'::jsonb, null, null, null, null, null, false, null, true),
  ('m_sitting', 6, 2, 'single', null, 'On a typical weekday, how many hours do you spend sitting?', 'Lectures, studying, travel and screen time together.', null, '[{"value": "<6", "label": "Less than 6 hours", "score": 2}, {"value": "6-9", "label": "6 to 9 hours", "score": 1}, {"value": "10+", "label": "10 hours or more", "score": 0}]'::jsonb, null, null, null, null, null, false, null, true),
  ('f_living', 7, 1, 'single', null, 'Where do you live during the semester?', null, null, '[{"value": "hostel", "label": "University hostel"}, {"value": "boarding", "label": "Boarding or rented room"}, {"value": "home", "label": "At home with family"}, {"value": "other", "label": "Somewhere else"}]'::jsonb, null, null, null, null, 'accommodation', false, null, true),
  ('f_money', 7, 2, 'single', null, 'How often do money worries affect your food, transport or health choices?', null, null, '[{"value": "never", "label": "Never", "score": 3}, {"value": "sometimes", "label": "Sometimes", "score": 2}, {"value": "often", "label": "Often", "score": 1}, {"value": "always", "label": "Almost always", "score": 0}]'::jsonb, null, null, null, null, null, false, null, true),
  ('o_talk', 8, 1, 'single', null, 'Do you have someone you can talk to when things get hard?', null, null, '[{"value": "always", "label": "Yes, always", "score": 2}, {"value": "sometimes", "label": "Sometimes", "score": 1}, {"value": "no", "label": "Not really", "score": 0}]'::jsonb, null, null, null, null, null, false, null, true),
  ('o_lonely', 8, 2, 'single', null, 'How often do you feel lonely on campus?', null, null, '[{"value": "never", "label": "Never", "score": 3}, {"value": "rarely", "label": "Rarely", "score": 2}, {"value": "sometimes", "label": "Sometimes", "score": 1}, {"value": "often", "label": "Often", "score": 0}]'::jsonb, null, null, null, null, null, false, null, true),
  ('c_food', 9, 1, 'scale', null, 'How easy is it to find healthy, affordable food on campus?', null, null, '[{"value": "1", "label": "Very hard", "score": 0}, {"value": "2", "label": "Hard", "score": 1}, {"value": "3", "label": "Okay", "score": 2}, {"value": "4", "label": "Easy", "score": 3}, {"value": "5", "label": "Very easy", "score": 4}]'::jsonb, null, null, null, null, null, false, null, true),
  ('c_health_centre', 9, 2, 'single', null, 'Have you used the university health centre this academic year?', null, null, '[{"value": "yes", "label": "Yes"}, {"value": "no_need", "label": "No, I did not need to"}, {"value": "no_barrier", "label": "No, I needed to but did not go"}]'::jsonb, null, null, null, null, null, false, null, true),
  ('c_barriers', 9, 3, 'multi', null, 'What makes it hard to use campus health services?', 'Select all that apply.', null, '[{"value": "unaware", "label": "Not sure what is offered"}, {"value": "hours", "label": "Opening hours"}, {"value": "waiting", "label": "Waiting time"}, {"value": "privacy", "label": "Privacy worries"}, {"value": "distance", "label": "Distance or transport"}, {"value": "uncomfortable", "label": "Feeling uncomfortable asking"}, {"value": "none", "label": "Nothing, it is easy"}]'::jsonb, null, null, null, null, null, false, null, true),
  ('v_challenges', 10, 1, 'multi', null, 'What are your main challenges right now?', 'Pick up to three.', null, '[{"value": "workload", "label": "Academic workload or exams"}, {"value": "emotional", "label": "Stress, low mood or emotional difficulties"}, {"value": "money", "label": "Money problems"}, {"value": "food_cost", "label": "Cost or availability of healthy food"}, {"value": "meals", "label": "Skipping breakfast or irregular meals"}, {"value": "inactive", "label": "Not enough physical activity"}, {"value": "sleep", "label": "Poor sleep"}, {"value": "substance", "label": "Smoking or substance use"}, {"value": "care", "label": "Getting healthcare or counselling"}, {"value": "living", "label": "Accommodation or transport"}, {"value": "other", "label": "Something else"}, {"value": "pns", "label": "Prefer not to say"}]'::jsonb, null, null, null, 3, null, false, null, true),
  ('v_priorities', 10, 2, 'multi', null, 'Pick up to three things the university should prioritise for student health.', null, null, '[{"value": "canteen", "label": "Healthier canteen food"}, {"value": "affordable", "label": "Affordable meals"}, {"value": "mental", "label": "Mental health and counselling"}, {"value": "fitness", "label": "Sports and fitness facilities"}, {"value": "water", "label": "Drinking water stations"}, {"value": "schedule", "label": "Better exam and study scheduling"}, {"value": "screening", "label": "Regular health screenings"}, {"value": "hostels", "label": "Safer, cleaner hostels"}, {"value": "education", "label": "Health workshops and education"}]'::jsonb, null, null, null, 3, null, false, null, true),
  ('v_problem', 10, 3, 'text', null, 'What is the biggest problem affecting student health or well-being at your university?', 'Optional. Please do not include names or anything that could identify you.', null, '[]'::jsonb, null, null, null, null, null, true, null, true),
  ('v_change', 10, 4, 'text', null, 'What change or support would you most like the university to provide?', 'Optional. Please do not include names or anything that could identify you.', null, '[]'::jsonb, null, null, null, null, null, true, null, true),
  ('k_source', 11, 1, 'single', null, 'Did you get your measurements at the university health centre?', 'Only enter values that were measured, not guesses.', null, '[{"value": "health_centre", "label": "Yes, at the university health centre"}, {"value": "clinic", "label": "No, at another clinic, hospital or pharmacy"}, {"value": "self", "label": "No, I measured them myself"}, {"value": "none", "label": "I don''t have recent measurements"}]'::jsonb, null, null, null, null, null, false, null, true),
  ('k_when', 11, 2, 'single', null, 'When were they measured?', null, null, '[{"value": "week", "label": "In the last week"}, {"value": "month", "label": "In the last month"}, {"value": "six", "label": "In the last 6 months"}, {"value": "older", "label": "More than 6 months ago"}]'::jsonb, null, null, null, null, null, false, '{"q": "k_source", "not_in": ["none"]}'::jsonb, true),
  ('k_height', 11, 3, 'number', null, 'Height', null, null, '[]'::jsonb, 'cm', 100, 230, null, 'height_cm', true, '{"q": "k_source", "not_in": ["none"]}'::jsonb, true),
  ('k_weight', 11, 4, 'number', null, 'Weight', null, null, '[]'::jsonb, 'kg', 25, 250, null, 'weight_kg', true, '{"q": "k_source", "not_in": ["none"]}'::jsonb, true),
  ('k_waist', 11, 5, 'number', null, 'Waist circumference', null, null, '[]'::jsonb, 'cm', 40, 200, null, 'waist_cm', true, '{"q": "k_source", "not_in": ["none"]}'::jsonb, true),
  ('k_hip', 11, 6, 'number', null, 'Hip circumference', null, null, '[]'::jsonb, 'cm', 50, 200, null, 'hip_cm', true, '{"q": "k_source", "not_in": ["none"]}'::jsonb, true),
  ('k_sbp', 11, 7, 'number', null, 'Blood pressure, upper number (systolic)', null, null, '[]'::jsonb, 'mmHg', 70, 250, null, 'sbp', true, '{"q": "k_source", "not_in": ["none"]}'::jsonb, true),
  ('k_dbp', 11, 8, 'number', null, 'Blood pressure, lower number (diastolic)', null, null, '[]'::jsonb, 'mmHg', 40, 150, null, 'dbp', true, '{"q": "k_source", "not_in": ["none"]}'::jsonb, true),
  ('k_fbg', 11, 9, 'number', null, 'Fasting blood glucose', 'Only from a fasting test (nothing to eat for 8 hours).', null, '[]'::jsonb, 'mg/dL', 40, 500, null, 'fbg', true, '{"q": "k_source", "not_in": ["none"]}'::jsonb, true),
  ('k_tg', 11, 10, 'number', null, 'Triglycerides', null, null, '[]'::jsonb, 'mg/dL', 20, 1500, null, 'tg', true, '{"q": "k_source", "not_in": ["none"]}'::jsonb, true),
  ('k_chol', 11, 11, 'number', null, 'Total cholesterol', null, null, '[]'::jsonb, 'mg/dL', 60, 600, null, 'chol', true, '{"q": "k_source", "not_in": ["none"]}'::jsonb, true);
